186	        at: usize,
187	        table_cap: usize,
188	        max_len: Option<usize>,
189	    ) {
190	        if let Some(max_len) = max_len {
191	            self.gated_lt_count(gate.clone(), lanes[at + 1].clone(), max_len);
192	        }
193	        let end = self.add(lanes[at].clone(), lanes[at + 1].clone());
194	        self.gated_lt_end(gate, end, table_cap);
195	    }
196	    /// Full structural validation of one 13-lane `FrameRowC` under `gate`,
197	    /// mirroring Core `frame_caps` field by field, including the builtin
198	    /// TypeId cap `max(max_types, 4)` and per-variant zero padding.
199	    #[allow(clippy::needless_range_loop)]
200	    pub(super) fn gated_validate_frame(
201	        &mut self,
202	        gate: Operand,
203	        frame: &[Operand],
204	        caps: &C6PhysCaps,
205	    ) {
206	        debug_assert_eq!(frame.len(), FRAME_LANES);
207	        let builtin_types = caps.max_types.max(4);
208	        let mut tag_bits = Vec::with_capacity(10);
209	        let mut tag_sum = Self::imm(0);
210	        for tag in 0..10 {
211	            let is_tag = self.teq(frame[0].clone(), Self::imm(tag as u128));
212	            tag_sum = self.add(tag_sum, is_tag.clone());
213	            tag_bits.push(is_tag);
214	        }
215	        self.geq(gate.clone(), tag_sum, Self::imm(1));
216	        // 0 LetF
217	        let gt = self.mul(gate.clone(), tag_bits[0].clone());
218	        self.gated_lt_index(gt.clone(), frame[1].clone(), caps.max_names);
219	        self.gated_lt_index(gt.clone(), frame[2].clone(), caps.max_expressions);
220	        self.gated_validate_env(
221	            gt.clone(),
222	            frame[3].clone(),
223	            frame[4].clone(),
224	            caps.max_env_cells,
225	        );
226	        self.gated_lt_index(gt, frame[5].clone(), caps.max_expressions);
227	        // 1 LeftF
228	        let gt = self.mul(gate.clone(), tag_bits[1].clone());
229	        self.gated_lt_index(gt.clone(), frame[1].clone(), 7);
230	        self.gated_lt_index(gt.clone(), frame[2].clone(), caps.max_expressions);
231	        self.gated_validate_env(
232	            gt.clone(),
233	            frame[3].clone(),
234	            frame[4].clone(),
235	            caps.max_env_cells,
236	        );
237	        self.gated_lt_index(gt, frame[5].clone(), caps.max_expressions);
238	        // 2 RightF
239	        let gt = self.mul(gate.clone(), tag_bits[2].clone());
240	        self.gated_lt_index(gt.clone(), frame[1].clone(), 7);
241	        self.gated_validate_ref(gt.clone(), frame, 2, caps);
242	        self.gated_lt_index(gt, frame[4].clone(), caps.max_expressions);
243	        // 3 UnaryF
244	        let gt = self.mul(gate.clone(), tag_bits[3].clone());
245	        self.gated_lt_index(gt.clone(), frame[1].clone(), 2);
246	        self.gated_lt_index(gt, frame[2].clone(), caps.max_expressions);
247	        // 4 IfF
248	        let gt = self.mul(gate.clone(), tag_bits[4].clone());
249	        self.gated_lt_index(gt.clone(), frame[1].clone(), caps.max_expressions);
250	        self.gated_lt_index(gt.clone(), frame[2].clone(), caps.max_expressions);
251	        self.gated_validate_env(
252	            gt.clone(),
253	            frame[3].clone(),
254	            frame[4].clone(),
255	            caps.max_env_cells,
256	        );
257	        self.gated_lt_index(gt, frame[5].clone(), caps.max_expressions);
258	        // 5 MatchF
259	        let gt = self.mul(gate.clone(), tag_bits[5].clone());
260	        self.gated_validate_slice(gt.clone(), frame, 1, caps.max_arms, None);
261	        self.gated_validate_env(
262	            gt.clone(),
263	            frame[3].clone(),
264	            frame[4].clone(),
265	            caps.max_env_cells,
266	        );
267	        self.gated_lt_index(gt, frame[5].clone(), caps.max_expressions);
268	        // 6 ArgsF
269	        let gt = self.mul(gate.clone(), tag_bits[6].clone());
270	        self.gated_lt_index(gt.clone(), frame[1].clone(), caps.max_names);
271	        self.gated_validate_slice(
272	            gt.clone(),
273	            frame,
274	            2,
275	            caps.max_value_slots,
276	            Some(caps.max_arity),
277	        );
278	        self.gated_validate_slice(
279	            gt.clone(),
280	            frame,
281	            4,
282	            caps.max_children,
283	            Some(caps.max_arity),
284	        );
285	        self.gated_validate_env(
286	            gt.clone(),
287	            frame[6].clone(),
288	            frame[7].clone(),
289	            caps.max_env_cells,
290	        );
291	        self.gated_lt_index(gt, frame[8].clone(), caps.max_expressions);
292	        // 7 ReturnF (builtin TypeId cap)
293	        let gt = self.mul(gate.clone(), tag_bits[7].clone());
294	        self.gated_lt_index(gt.clone(), frame[1].clone(), builtin_types);
295	        self.gated_validate_env(
296	            gt.clone(),
297	            frame[2].clone(),
298	            frame[3].clone(),
299	            caps.max_env_cells,
300	        );
301	        self.gated_lt_index(gt, frame[4].clone(), caps.max_expressions);
302	        // 8 ScopeF
303	        let gt = self.mul(gate.clone(), tag_bits[8].clone());
304	        self.gated_validate_env(
305	            gt.clone(),
306	            frame[1].clone(),
307	            frame[2].clone(),
308	            caps.max_env_cells,
309	        );
310	        self.gated_lt_index(gt, frame[3].clone(), caps.max_expressions);
311	        // 9 ConstructorFieldsF (builtin TypeId caps)
312	        let gt = self.mul(gate.clone(), tag_bits[9].clone());
313	        self.gated_lt_index(gt.clone(), frame[1].clone(), builtin_types);
314	        self.gated_lt_index(gt.clone(), frame[2].clone(), caps.max_constructors);
315	        self.gated_lt_index(gt.clone(), frame[3].clone(), caps.max_arity);
316	        self.gated_lt_index(gt.clone(), frame[4].clone(), builtin_types);
317	        self.gated_boolean(gt.clone(), frame[5].clone());
318	        self.gated_validate_slice(
319	            gt.clone(),
320	            frame,
321	            6,
322	            caps.max_value_slots,
323	            Some(caps.max_arity),
324	        );
325	        self.gated_validate_slice(
326	            gt.clone(),
327	            frame,
328	            8,
329	            caps.max_children,
330	            Some(caps.max_arity),
331	        );
332	        self.gated_validate_env(
333	            gt.clone(),
334	            frame[10].clone(),
335	            frame[11].clone(),
336	            caps.max_env_cells,
337	        );
338	        self.gated_lt_index(gt, frame[12].clone(), caps.max_expressions);
339	        // Zero padding of unused lanes per variant.
340	        const USED: [usize; 10] = [6, 6, 5, 3, 6, 6, 9, 5, 4, 13];
341	        for lane in 1..FRAME_LANES {
342	            let mut must_zero = Self::imm(0);
343	            let mut any = false;
344	            for (tag, used) in USED.iter().enumerate() {
345	                if lane >= *used {
346	                    must_zero = self.add(must_zero, tag_bits[tag].clone());
347	                    any = true;
348	                }
349	            }
350	            if any {
351	                let pad_gate = self.mul(gate.clone(), must_zero);
352	                self.geq(pad_gate, frame[lane].clone(), Self::imm(0));
353	            }
354	        }
355	    }
356	}
