431	pub(super) fn check_shapes(inputs: &C6StepInputs) -> Result<(), String> {
432	    if 129usize >= FR_BITS {
433	        return Err("129-bit comparator exceeds the field".into());
434	    }
435	    inputs
436	        .source_params
437	        .validate_geometry(inputs.geometry)
438	        .map_err(bk)?;
439	    let g = &inputs.geometry;
440	    for (s, a, e) in [
441	        ("pre image", inputs.pre_image.len(), g.image_total_lanes),
442	        ("post image", inputs.post_image.len(), g.image_total_lanes),
443	        ("pre data", inputs.pre_data.len(), g.data_total_lanes),
444	        ("post data", inputs.post_data.len(), g.data_total_lanes),
445	        ("pre helper", inputs.pre_helper.len(), g.helper_total_lanes),
446	        (
447	            "post helper",
448	            inputs.post_helper.len(),
449	            g.helper_total_lanes,
450	        ),
451	    ] {
452	        if a != e {
453	            return Err(format!("length mismatch in {s}: expected {e}, got {a}"));
454	        }
455	    }
456	    if inputs.pre_meta.len() < 3
457	        || inputs.pre_meta.len() != inputs.post_meta.len()
458	        || inputs.pre_prog.len() != inputs.post_prog.len()
459	        || inputs.meta_bounds_frames_offset >= inputs.pre_meta.len()
460	    {
461	        return Err("host prefix length/offset".into());
462	    }
463	    Ok(())
464	}
