466	/// Fixed schema/carrier, unconditional prefix equality and lane ranges.
467	pub(super) fn prefix(em: &mut Em, inputs: &C6StepInputs) {
468	    let en = inputs.enable.clone();
469	    em.cbool(en.clone());
470	    em.ceq(inputs.host_schema.clone(), Em::imm(C6_HOST_SCHEMA));
471	    em.ceq(
472	        inputs.carrier_version.clone(),
473	        Em::imm(C6_PADDED_CARRIER_VERSION),
474	    );
475	    for (a, b) in inputs
476	        .pre_meta
477	        .iter()
478	        .zip(inputs.post_meta.iter())
479	        .chain(inputs.pre_prog.iter().zip(inputs.post_prog.iter()))
480	        .chain(inputs.pre_ctx.iter().zip(inputs.post_ctx.iter()))
481	    {
482	        em.cbits(a.clone());
483	        em.cbits(b.clone());
484	        em.ceq(b.clone(), a.clone());
485	    }
486	    em.geq(
487	        en.clone(),
488	        inputs.pre_meta[0].clone(),
489	        Em::imm(C6_PHYS_MAGIC),
490	    );
491	    em.geq(
492	        en.clone(),
493	        inputs.pre_meta[1].clone(),
494	        Em::imm(C6_PHYS_VERSION),
495	    );
496	    em.geq(
497	        en.clone(),
498	        inputs.pre_ctx[0].clone(),
499	        Em::imm(C6_PHYS_MAGIC),
500	    );
501	    em.geq(
502	        en.clone(),
503	        inputs.pre_ctx[1].clone(),
504	        Em::imm(C6_PHYS_VERSION),
505	    );
506	    for l in inputs
507	        .pre_image
508	        .iter()
509	        .chain(inputs.post_image.iter())
510	        .chain(inputs.pre_data.iter())
511	        .chain(inputs.post_data.iter())
512	        .chain(inputs.pre_helper.iter())
513	        .chain(inputs.post_helper.iter())
514	    {
515	        em.cbits(l.clone());
516	    }
517	}
