612	/// LegacyComplete charge: work 1 and reference cursor 1, checked 128-bit.
613	pub(super) fn charge_legacy(em: &mut Em, inputs: &C6StepInputs) {
614	    let en = inputs.enable.clone();
615	    let pre_i = &inputs.pre_image;
616	    let post_i = &inputs.post_image;
617	    let dec = em.add(post_i[L_REMAINING_WORK].clone(), Em::imm(1));
618	    em.geq(en.clone(), dec, pre_i[L_REMAINING_WORK].clone());
619	    for lane in [L_CONSUMED_WORK, L_REFERENCE_CURSOR] {
620	        let no_overflow = em.lt128(pre_i[lane].clone(), Em::imm(u128::MAX));
621	        em.gassert(en.clone(), no_overflow);
622	        let inc = em.add(pre_i[lane].clone(), Em::imm(1));
623	        em.geq(en.clone(), post_i[lane].clone(), inc);
624	    }
625	}
