627	/// Under enable, post control lanes equal `control` exactly.
628	pub(super) fn set_control(em: &mut Em, inputs: &C6StepInputs, control: &[Operand]) {
629	    debug_assert_eq!(control.len(), CONTROL_LANES);
630	    for (off, want) in control.iter().enumerate() {
631	        em.geq(
632	            inputs.enable.clone(),
633	            inputs.post_image[L_CONTROL + off].clone(),
634	            want.clone(),
635	        );
636	    }
637	}
