639	/// Under enable, every image header lane not in `mutable` and every frame
640	/// slot lane is preserved.
641	pub(super) fn preserve_image(
642	    em: &mut Em,
643	    inputs: &C6StepInputs,
644	    mutable: &[usize],
645	    frames_mutable: bool,
646	) {
647	    let en = inputs.enable.clone();
648	    for lane in 0..IMAGE_SECTION_HEADER_LANES {
649	        if !mutable.contains(&lane) {
650	            em.geq(
651	                en.clone(),
652	                inputs.post_image[lane].clone(),
653	                inputs.pre_image[lane].clone(),
654	            );
655	        }
656	    }
657	    if !frames_mutable {
658	        for lane in IMAGE_SECTION_HEADER_LANES..inputs.pre_image.len() {
659	            em.geq(
660	                en.clone(),
661	                inputs.post_image[lane].clone(),
662	                inputs.pre_image[lane].clone(),
663	            );
664	        }
665	    }
666	}
