668	/// The header lanes a LegacyComplete control rewrite may change.
669	pub(super) fn legacy_control_lanes() -> Vec<usize> {
670	    let mut v: Vec<usize> = (L_CONTROL..L_CONTROL + CONTROL_LANES).collect();
671	    v.extend([L_REMAINING_WORK, L_CONSUMED_WORK, L_REFERENCE_CURSOR]);
672	    v
673	}
