675	/// Retained-serial composition of META/PROG/CTX/DATA/HELPER canonicality.
676	pub(super) fn compose_canonical(
677	    composed: &mut Composed,
678	    em: &mut Em,
679	    inputs: &C6StepInputs,
680	) -> Result<(), String> {
681	    let en = inputs.enable.clone();
682	    let caps = inputs.geometry.caps;
683	    let mb = composed
684	        .meta_em
685	        .emit_bound(&C6MetaBoundCanonicalInputs {
686	            gate: en.clone(),
687	            pre_meta: inputs.pre_meta.clone(),
688	            post_meta: inputs.post_meta.clone(),
689	            limits: inputs.source_params.limits(),
690	            meta_bounds_frames_offset: inputs.meta_bounds_frames_offset,
691	            binding: inputs.source_params.meta_binding(),
692	        })
693	        .map_err(bk)?;
694	    em.ins.extend(mb.instructions);
695	    let pc = composed
696	        .progctx_em
697	        .emit(&C6ProgramContextCanonicalInputs {
698	            gate: en.clone(),
699	            pre_prog: inputs.pre_prog.clone(),
700	            pre_ctx: inputs.pre_ctx.clone(),
701	            caps,
702	        })
703	        .map_err(bk)?;
704	    em.ins.extend(pc.instructions);
705	    let cx = composed
706	        .progctx_em
707	        .emit_ctx_binding(&C6ProgramContextCtxBindingInputs {
708	            gate: en.clone(),
709	            pre_ctx: inputs.pre_ctx.clone(),
710	            expected_ctx: inputs.source_params.expected_ctx(),
711	        })
712	        .map_err(bk)?;
713	    em.ins.extend(cx.instructions);
714	    for data in [&inputs.pre_data, &inputs.post_data] {
715	        let db = composed
716	            .data_em
717	            .emit(&C6DataCanonicalInputs {
718	                gate: en.clone(),
719	                data: data.clone(),
720	                caps,
721	            })
722	            .map_err(bk)?;
723	        em.ins.extend(db.instructions);
724	    }
725	    for helper in [&inputs.pre_helper, &inputs.post_helper] {
726	        let hb = composed
727	            .helper_em
728	            .emit(&C6HelperCanonicalInputs {
729	                gate: en.clone(),
730	                helper: helper.clone(),
731	                caps,
732	            })
733	            .map_err(bk)?;
734	        em.ins.extend(hb.instructions);
735	    }
736	    Ok(())
737	}
