739	/// Disabled: the full post state equals the pre state.
740	pub(super) fn disabled_identity(em: &mut Em, inputs: &C6StepInputs) {
741	    let disabled = em.not(inputs.enable.clone());
742	    for (a, b) in inputs
743	        .pre_image
744	        .iter()
745	        .zip(inputs.post_image.iter())
746	        .chain(inputs.pre_data.iter().zip(inputs.post_data.iter()))
747	        .chain(inputs.pre_helper.iter().zip(inputs.post_helper.iter()))
748	    {
749	        em.geq(disabled.clone(), b.clone(), a.clone());
750	    }
751	}
