815	/// Frame pop: post depth + 1 = pre depth (> 0), the popped top slot is all
816	/// zero after the step, every other slot is preserved. Pair with
817	/// `preserve_image(.., frames_mutable = true)` and `L_FRAME_COUNT` mutable.
818	pub(super) fn pop_frame(em: &mut Em, inputs: &C6StepInputs) {
819	    use mori_core::sherlock::helper_machine::c6_phys::L_FRAME_COUNT;
820	    let en = inputs.enable.clone();
821	    let pre_i = &inputs.pre_image;
822	    let post_i = &inputs.post_image;
823	    let depth = pre_i[L_FRAME_COUNT].clone();
824	    let some = em.lt128(Em::imm(0), depth.clone());
825	    em.gassert(en.clone(), some);
826	    let back = em.add(post_i[L_FRAME_COUNT].clone(), Em::imm(1));
827	    em.geq(en.clone(), back, depth.clone());
828	    let p = &inputs.geometry.caps.phys;
829	    for slot in 0..p.max_frames {
830	        let base = IMAGE_SECTION_HEADER_LANES + slot * FRAME_LANES;
831	        let top = em.teq(Em::imm(slot as u128 + 1), depth.clone());
832	        for lane in base..base + FRAME_LANES {
833	            let want = em.sel(top.clone(), Em::imm(0), pre_i[lane].clone());
834	            em.geq(en.clone(), post_i[lane].clone(), want);
835	        }
836	    }
837	}
