47	// Helper result tags (c6_phys_helper::encode_result_record).
48	const R_FIND_FOUND: u128 = 5;
49	const R_BIND_OK: u128 = 7;
50	
51	#[derive(Clone, Debug)]
52	pub struct C6CallBindBlock {
53	    pub instructions: Vec<Instruction>,
54	}
