56	pub struct C6CallBindEmitter {
57	    scope: String,
58	    next_temp: usize,
59	    composed: Composed,
60	}
61	
62	impl C6CallBindEmitter {
63	    pub fn new(scope: &str) -> Result<Self, C6CallBindError> {
64	        if scope.trim().is_empty() || scope.contains('%') || scope.contains(".c6kit.") {
65	            return Err(C6CallBindError::InvalidScope);
66	        }
67	        Ok(Self {
68	            scope: scope.to_string(),
69	            next_temp: 0,
70	            composed: Composed::new(scope).map_err(C6CallBindError::Emit)?,
71	        })
72	    }
73	
74	    pub fn emit(
75	        &mut self,
76	        rule: RuleIdC,
77	        inputs: &C6StepInputs,
78	    ) -> Result<C6CallBindBlock, C6CallBindError> {
79	        if !call_bind_supported(rule) {
80	            return Err(C6CallBindError::Unsupported(rule));
81	        }
82	        check_shapes(inputs).map_err(C6CallBindError::Emit)?;
83	        let scope = self.scope.clone();
84	        let mut em = Em {
85	            scope: &scope,
86	            next: self.next_temp,
87	            ins: Vec::new(),
88	        };
89	        let r = self.body(&mut em, rule, inputs);
90	        self.next_temp = em.next;
91	        r.map_err(C6CallBindError::Emit)?;
92	        Ok(C6CallBindBlock {
93	            instructions: em.ins,
94	        })
95	    }
96	
97	    fn body(&mut self, em: &mut Em, rule: RuleIdC, inputs: &C6StepInputs) -> Result<(), String> {
98	        let en = inputs.enable.clone();
99	        prefix(em, inputs);
100	        let _top = validate_pre_image(em, inputs);
101	        select(&mut self.composed, em, rule, inputs)?;
102	
103	        let pre_i = &inputs.pre_image;
104	        let k = &pre_i[L_CONTROL..L_CONTROL + CONTROL_LANES];
105	        let res = &inputs.pre_helper[L_RESULT_RECORD..L_RESULT_RECORD + RESULT_LANES];
106	        let mut ctl: Vec<Operand> = (0..CONTROL_LANES).map(|_| Em::imm(0)).collect();
107	        let clears_result = match rule {
108	            RuleIdC::KMachineInvokeFind => {
109	                // Invoke { fname, args } + Find result -> Enter { function?, args }.
110	                em.geq(en.clone(), k[0].clone(), Em::imm(3));
111	                let found = em.teq(res[0].clone(), Em::imm(R_FIND_FOUND));
112	                ctl[0] = Em::imm(4);
113	                ctl[1] = found.clone();
114	                ctl[2] = em.mul(found, res[1].clone());
115	                ctl[3] = k[2].clone();
116	                ctl[4] = k[3].clone();
117	                true
118	            }
119	            RuleIdC::KMachineEnterBind => {
120	                // Enter { Some(f), args } + Bind result -> Bound { binding,
121	                // f.return_type, f.body }.
122	                em.geq(en.clone(), k[0].clone(), Em::imm(4));
123	                em.geq(en.clone(), k[1].clone(), Em::imm(1));
124	                let f = self
125	                    .composed
126	                    .progctx_em
127	                    .emit_prog_function_capture(&C6ProgramContextFunctionCaptureInputs {
128	                        gate: en.clone(),
129	                        pre_prog: inputs.pre_prog.clone(),
130	                        caps: inputs.geometry.caps,
131	                        function_index: k[2].clone(),
132	                    })
133	                    .map_err(|e| e.to_string())?;
134	                em.ins.extend(f.instructions);
135	                em.gassert(en.clone(), f.function_found.clone());
136	                let ok = em.teq(res[0].clone(), Em::imm(R_BIND_OK));
137	                ctl[0] = Em::imm(5);
138	                ctl[1] = ok.clone();
139	                ctl[2] = em.mul(ok.clone(), res[1].clone());
140	                ctl[3] = em.mul(ok, res[2].clone());
141	                ctl[4] = f.function_row[3].clone();
142	                ctl[5] = f.function_row[4].clone();
143	                true
144	            }
145	            RuleIdC::KMachineBoundValid => {
146	                // Bound { Ok { env }, return_type, body } -> ScheduleNext {
147	                // ReturnF { return_type, saved_env: env_root, origin:
148	                // control_origin }, next: body, env }.
149	                em.geq(en.clone(), k[0].clone(), Em::imm(5));
150	                em.geq(en.clone(), k[1].clone(), Em::imm(1));
151	                ctl[0] = Em::imm(2);
152	                ctl[1] = Em::imm(7);
153	                ctl[2] = k[4].clone();
154	                ctl[3] = pre_i[L_ENV_ROOT].clone();
155	                ctl[4] = pre_i[L_ENV_ROOT + 1].clone();
156	                ctl[5] = pre_i[L_CONTROL_ORIGIN].clone();
157	                ctl[14] = k[5].clone();
158	                ctl[15] = k[2].clone();
159	                ctl[16] = k[3].clone();
160	                false
161	            }
162	            _ => unreachable!("checked by call_bind_supported"),
163	        };
164	        set_control(em, inputs, &ctl);
165	        preserve_image(em, inputs, &legacy_control_lanes(), false);
166	        charge_legacy(em, inputs);
167	        for (a, b) in inputs.pre_data.iter().zip(inputs.post_data.iter()) {
168	            em.geq(en.clone(), b.clone(), a.clone());
169	        }
170	        for (lane, (a, b)) in inputs
171	            .pre_helper
172	            .iter()
173	            .zip(inputs.post_helper.iter())
174	            .enumerate()
175	        {
176	            let in_result = (L_RESULT_RECORD..L_RESULT_RECORD + RESULT_LANES).contains(&lane);
177	            if clears_result && in_result {
178	                em.gzero(en.clone(), b.clone());
179	            } else {
180	                em.geq(en.clone(), b.clone(), a.clone());
181	            }
182	        }
183	        compose_canonical(&mut self.composed, em, inputs)?;
184	        disabled_identity(em, inputs);
185	        Ok(())
186	    }
187	}
188	
189	/// One-shot emission of the CallBind control relation for `rule`.
190	pub fn emit_c6_call_bind_block(
191	    rule: RuleIdC,
192	    inputs: &C6StepInputs,
193	    scope: &str,
194	) -> Result<C6CallBindBlock, C6CallBindError> {
195	    C6CallBindEmitter::new(scope)?.emit(rule, inputs)
196	}
